function una(fn) {
  let hecho = false;
  let resultado;
  return (...args) => {
    if (!hecho) {
      hecho = true;
      resultado = fn(...args);
    }
    return resultado;
  };
}
const iniciar = una((x) => x * 2);
console.log(iniciar(5), iniciar(10));
